class Appointment_Record {

    // Properties
    # Appointment ID Generated By Firestore Or Code Generated?? -- Using Document ID First
    private string $appointmentid;

    # Appointment Status (Upcoming, Missed, etc...) -- Need To Call A Function To Update Status When Directed To The Page or Reload
    private string $appointmentstatus;

    # Appointment Type (e.g. Specialist, Doctor Consultation)
    private string $appointmenttype;

    # Appointment Date & Time [e.g. 01-01-2021]
    private Time $scheduledon;

    # Appointment Venue (The Location)
    private Medical_Facility $facility;

    # Appointment Created on (Date & Time)
    private Time $createdon;

    protected const APPOINTMENT_RECORD = "Appointment_Record";

    // Constructor
    function __construct(Time $createdon, Time $scheduledon, string $appointmentid, string $appointmenttype, Medical_Facility $facility) {
        $this->createdon = $createdon;
        $this->scheduledon = $scheduledon;
        $this->appointmentid = $appointmentid;
        $this->appointmenttype = $appointmenttype;
        $this->appointmentstatus = Appointment_Status::UPCOMING;
        $this->facility = $facility; // -- Medical_Facility Object -- //
    }

    // Getters
    public function get_appointmentid(): string {
        return $this->appointmentid;
    }

    public function get_appointmenttype(): string {
        return $this->appointmenttype;
    }

    public function get_appointmentstatus(): string {
        return $this->appointmentstatus;
    }

    public function get_scheduledon(): Time {
        return $this->scheduledon;
    }

    public function get_facility(): Medical_Facility {
        return $this->facility;
    }

    // Setters
    public function set_appointmentstatus(string $appointmentstatus): void {
        $this->appointmentstatus = $appointmentstatus;
    }

    public function set_appointmenttype(string $appointmenttype): void {
        $this->appointmenttype = $appointmenttype;
    }

    public function set_date(string $date): void {
        $this->date = $date;
    }

    public function set_time(string $time): void {
        $this->time = $time;
    }

    // Use For Debugging/ Logging Purpose
    public function __toString(): string {
        $str = nl2br(PHP_EOL . "Created On: " . $this->createdon . PHP_EOL . 'Appointment ID: ' . $this->appointmentid .
                PHP_EOL . 'Appointment Status ' . $this->appointmentstatus .
                PHP_EOL . 'Scheduled On: ' . $this->scheduledon . PHP_EOL
                . 'Location ' . $this->facility);
        return $str;
    }

    //============================================
    //      Methods Accessing Firestore Database 
    //============================================
    // -- Create Appointment -- //
    public static function create_appointment(array $appointment_info): void {


        $appointment_info['createdon'] = (string) date("d-m-Y");

        $db = new DbQuery();
        $db->insert_data(self::APPOINTMENT_RECORD, $appointment_info);
    }

    private static function get_patient_appointment(array $email, array $appointmentstatus): array {
        # Array Of Appointments
        $appointment_arr = array();

        # Query For Upcoming Appointment Records
        $db = new DbQuery();
        $record_list = $db->get_nested_collection(Database::ACCOUNT_USER, Database::APPOINTMENT_RECORD,
                $email, $appointmentstatus);

        # Create Appointment Record Object List
        foreach ($record_list as $record) {
            $facility = Medical_Facility::get_facility_by_id($record['facilityid']);
            $scheduledon = new Time($record['scheduledon']['date'], $record['scheduledon']['time']);
            $createdon = new Time($record['createdon']['date'], $record['createdon']['time']);
            $record_object = new Appointment_Record($createdon, $scheduledon, $record['appointmentid'], $record['appointmenttype'],
                    $facility);
            $appointment_arr[] = $record_object;
        }
        return $appointment_arr;
    }

    // -- Get Upcoming Appointment By Patient (Array Of Appointment_Record) -- //
    public static function get_upcoming_appointments(array $email): array {

        # Set Default Appointment Status
        $appointmentstatus['appointmentstatus'] = Appointment_Status::UPCOMING;

        # Retrieving List Of Upcoming Appointments
        $upcoming_arr = self::get_patient_appointment($email, $appointmentstatus);

        return $upcoming_arr;
    }

    // -- Get Missed Appointment By Patient (Array Of Appointment Record)  last 14 days -- //
    public static function get_missed_appointments(array $email): array {

        # Set Default Appointment Status
        $appointmentstatus['appointmentstatus'] = Appointment_Status::MISSED;

        # Retrieving List Of Missed Appointments
        $missed_arr = self::get_patient_appointment($email, $appointmentstatus);

        return $missed_arr;
    }

